function Landing({onStart,onPricing}:{onStart:()=>void;onPricing:()=>void}){return <section className="hero"><div className="hero-copy"><span className="eyebrow"><span className="live-dot"/> THINK WELL, EVERY DAY</span><h1>Unlimited AI,<br/><em>earned by thinking.</em></h1><p>Build focus, memory, and confidence with small, meaningful moments of independent thought.</p><div className="button-row hero-actions"><button className="btn btn-primary btn-large" onClick={onStart}>Get Started <ArrowRight size={17}/></button><button className="btn btn-secondary btn-large" onClick={onPricing}>Pricing Plans</button></div><div className="hero-proof"><span><ShieldCheck size={15}/> Private by design</span><span><Leaf size={15}/> Progress over pressure</span></div></div><div className="hero-art"><div className="orb orb-a"/><div className="orb orb-b"/><div className="hero-card balance-float"><div className="mini-card-head"><div className="mini-icon teal"><Brain size={18}/></div><span className="quiet">THIS WEEK</span></div><div className="float-score">72<span>/100</span></div><div className="sparkline"><i/><i/><i/><i/><i/><i/><i/></div><div className="float-foot"><span>Independent thinking</span><span className="up-chip"><ArrowUpRight size={13}/> 8%</span></div></div><div className="hero-card credit-float"><div className="mini-icon amber"><Sparkles size={17}/></div><div><strong>Think Credits</strong><span>Earned by showing up</span></div><span className="credit-count">+12</span></div><div className="hero-seal"><div className="seal-circle"><Focus size={25}/></div><span>little steps<br/>add up</span></div></div><div className="hero-bottom"><span className="hero-count">01 <i/> 03</span><span className="quiet">A calmer way to grow with AI</span></div></section>}
