 const [search,setSearch]=useState('');const student=role==='Teacher',parent=role==='Parent',unit=parent?'children':student?'students':'workers';const observed=people.flatMap(p=>skills.map(s=>p.skills[s].debt));const debt=average(observed),repaid=average(people.flatMap(p=>skills.map(s=>p.skills[s].repaid)));const attention=summary.attention||71,recall=summary.recall||74;const perSkill=skills.map(s=>({skill:s,avg:average(people.map(p=>100-p.skills[s].debt)),debt:average(people.map(p=>p.skills[s].debt))}));const support=people.filter(p=>Math.max(...skills.map(s=>p.skills[s].debt))>35);const supervisorSections=['Overview','Learning analytics','Balance sheet','Cognitive Games','Challenges','Focus session','Wander break','Credits','Progress','People','Suggestions'];const breakToday=db.transactions.filter(t=>t.userId===user.id&&t.reason==='Eligible break completed'&&new Date(t.at).toDateString()===new Date().toDateString()).length;const spent=db.transactions.filter(t=>t.userId===user.id&&t.amount<0).reduce((n,t)=>n-t.amount,0);const personalChartData=Array.from({length:7},(_,ix)=>{const day=new Date(Date.now()-(6-ix)*86400000);const daily=user.sessions.filter(s=>new Date(s.date).toDateString()===day.toDateString());const attentionRows=daily.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus'));const recallRows=daily.filter(s=>s.skill==='Memory');return{day:day.toLocaleDateString(undefined,{weekday:'short'}),Attention:attentionRows.length?average(attentionRows.map(s=>s.score)):null,Recall:recallRows.length?average(recallRows.map(s=>s.score)):null,Earned:daily.reduce((n,s)=>n+s.creditsEarned,0),Debt:average(skills.map(sk=>user.skills[sk].debt)),Repaid:average(skills.map(sk=>user.skills[sk].repaid))}});const personalRadar=skills.map(skill=>{const rows=user.sessions.filter(s=>s.skill===skill);return{skill,Observed:rows.length?average(rows.map(s=>s.score)):Math.max(0,100-user.skills[skill].debt),Practised:user.skills[skill].repaid}});const totalHours=people.reduce